Accounts.roleName=function(code){const r=this.roles.find(r=>r.code===code);return I18n.language==='en'?(r?.name_en||I18n.translate(r?.name||this.names[code]||'历史角色',true)):(r?.name||this.names[code]||'历史角色');};
Object.assign(Accounts.groups,{plan:'销售管理',dispatch:'销售管理','vehicle-arrival':'装车计划管理','loading-plan':'装车计划管理',document:'出库与单证','packing-template':'出库与单证',load:'出库与单证',outbound:'出库与单证',allocation:'备货作业',lot:'备货作业',stocktake:'库存盘点与调整',adjust:'库存盘点与调整',move:'库存查询与库存地图',report:'统计报表',users:'系统及账户管理',roles:'系统及账户管理',system:'系统及账户管理',audit:'系统及账户管理'});
