Accounts.createRole=function(existing){dialog(existing?'编辑角色名称':'新增角色',`<form id="account-new-role" class="account-form"><p>添加角色后，请核实权限及账号数据范围，再分配给员工。</p><label>角色名称<input name="name" required maxlength="80" value="${esc(existing?.name||'')}"></label><label>英文角色名称<input name="name_en" maxlength="120" value="${esc(existing?.name_en||'')}"></label>${!existing?`<label>权限起点<select name="source"><option value="">空白角色，创建后配置</option><option value="preset:sales">销售与派车</option><option value="preset:viewer">库存只读</option>${this.roles.map(r=>`<option value="role:${r.code}" data-no-i18n>${esc(I18n.translate('复制现有角色')+' · '+this.roleName(r.code))}</option>`).join('')}</select></label>`:''}<p class="dialog-notice">${I18n.translate('权限会自动包含业务所需的查看权限。')}</p><p class="error" id="new-role-error" role="alert"></p><button class="button primary">${existing?'保存角色名称':'创建角色'}</button></form>`);$('account-new-role').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const data=Object.fromEntries(new FormData(e.target)),body={name:data.name,name_en:data.name_en};if(existing)body.version=existing.version;else if(data.source?.startsWith('preset:'))body.preset=data.source.slice(7);else if(data.source?.startsWith('role:'))body.copy_from=data.source.slice(5);const r=await API.request('/security/roles'+(existing?'/'+existing.code:''),{method:existing?'PATCH':'POST',body});this.selectedRole=r.code;this.tab='roles';$('dialog').close();await this.render();if(r.warnings?.length)notify(r.warnings.join('；'));}catch(err){$('new-role-error').textContent=err.message;e.submitter.disabled=false;}};I18n.apply();};
Accounts.drawRoles=function(){const roleCode=this.selectedRole&&this.roles.some(r=>r.code===this.selectedRole)?this.selectedRole:this.roles[0]?.code;if(!roleCode)return;let code=roleCode,dirty=false;const legacy=new Set(this.permissionCatalog?.legacy||[]),deps=this.permissionCatalog?.dependencies||{};
 $('account-content').innerHTML=`<div class="account-role-layout"><aside class="account-role-picker"><h2>选择角色</h2>${this.roles.map(r=>`<button class="button secondary" data-role="${r.code}" data-no-i18n>${esc(this.roleName(r.code))}</button>`).join('')}</aside><form id="account-role-form"><div class="business-toolbar"><h2 id="account-role-title" data-no-i18n></h2><button type="button" id="role-rename" class="button secondary">编辑角色名称</button></div><p>权限变更影响该角色全部账号，并撤销旧会话。</p><p>权限会自动包含业务所需的查看权限。</p><p id="role-risk" class="dialog-notice" role="status"></p><div id="account-permissions" class="account-permission-grid"></div><p id="role-dirty" aria-live="polite"></p><button class="button primary" id="role-save">保存权限</button> <button type="button" class="button secondary" id="role-reset">恢复未保存修改</button></form></div>`;
 const values=()=>[...document.querySelectorAll('#account-permissions input:checked')].map(x=>x.value),expand=ps=>{const out=new Set(ps);for(let change=true;change;){change=false;for(const p of [...out])for(const d of deps[p]||[])if(!out.has(d)){out.add(d);change=true;}}return out;},risk=()=>{const r=this.roles.find(r=>r.code===code),ps=values();$('role-risk').textContent=code==='admin'?'系统管理员保留账户与权限管理能力，业务权限可按职责配置。':ps.some(p=>!(r.recommended_permissions||[]).includes(p)||['users:manage','roles:manage','system:manage','audit:read'].includes(p))?'风险提示：所选权限可能超出本角色日常职责，或包含账户、权限及日志管理能力。允许保存，请确认实际职责与授权范围。':'请按实际工作职责选择权限。';I18n.apply();};
 const label=p=>this.permissionCatalog?.workflow?.[p]?.[I18n.language==='en'?'en':'zh']||this.permissionLabels[p]||((this.subjects[p.split(':')[0]]||p.split(':')[0])+' · '+(this.ops[p.split(':')[1]]||p.split(':')[1]));
 const draw=()=>{const r=this.roles.find(r=>r.code===code),groups={};this.selectedRole=code;for(const p of r.caps)(groups[legacy.has(p)?'历史单据兼容权限':this.permissionCatalog?.workflow?.[p]?.[I18n.language==='en'?'module_en':'module_zh']||this.groups[p.split(':')[0]]||'其他授权业务']||=[]).push(p);$('account-role-title').textContent=this.roleName(code);$('role-rename').hidden=r.built_in;$('role-rename').onclick=()=>this.createRole(r);$('account-permissions').innerHTML=Object.entries(groups).map(([name,ps])=>{const inner=ps.map(p=>`<label class="check-row"><input type="checkbox" value="${p}" ${r.permissions.includes(p)?'checked':''} ${code==='admin'&&this.permissionCatalog?.workflow?.[p]?.protected_admin?'disabled':''}><span>${esc(label(p))}${this.permissionCatalog?.workflow?.[p]?.product_roles?.CO_HYDROXIDE?'<small class="permission-product-limit">'+(I18n.language==='en'?'Cobalt: ':'钴：')+this.permissionCatalog.workflow[p].product_roles.CO_HYDROXIDE.map(code=>esc(this.roleName(code))).join(' / ')+'</small>':''}</span></label>`).join('');return name==='历史单据兼容权限'?`<details class="legacy-permissions"><summary>${name}</summary>${inner}</details>`:`<fieldset><legend>${name}</legend>${inner}</fieldset>`;}).join('');$('role-save').disabled=false;$('role-dirty').textContent='';dirty=false;for(const b of document.querySelectorAll('[data-role]'))b.classList.toggle('selected',b.dataset.role===code);risk();};
 for(const b of document.querySelectorAll('[data-role]'))b.onclick=()=>{if(dirty){$('role-dirty').textContent='请先保存或恢复未保存修改';return;}code=b.dataset.role;draw();};$('role-reset').onclick=draw;$('account-role-form').onchange=()=>{const ps=expand(values());for(const input of document.querySelectorAll('#account-permissions input'))input.checked=ps.has(input.value);dirty=true;$('role-dirty').textContent='有未保存的权限修改';risk();};$('account-role-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const r=await API.request('/security/roles/'+code,{method:'PUT',body:{permissions:values(),version:this.roles.find(r=>r.code===code).version}});Object.assign(this.roles.find(r=>r.code===code),{permissions:r.permissions,version:r.version});draw();notify(r.warnings?.join('；')||'权限已更新，相关会话已撤销。');}catch(err){this.error(err);e.submitter.disabled=false;}};draw();I18n.apply();};
const roleRender=Accounts.render.bind(Accounts);Accounts.render=async function(){await roleRender();if(Business.can('roles:manage')){const b=document.createElement('button');b.id='account-create-role';b.className='button primary';b.textContent='新增角色';b.onclick=()=>this.createRole();document.querySelector('.account-tabs').append(b);I18n.apply();}};
const documentDetail=Shipping.detail.bind(Shipping);Shipping.detail=async function(id){await documentDetail(id);const d=this.data;if(d.document?.includes_invoice&&!d.document_stale){const tabs=document.createElement('div');tabs.className='business-toolbar document-sheet-tabs';tabs.innerHTML='<button type="button" class="button secondary" data-document-sheet="INV">发票</button><button type="button" class="button primary" data-document-sheet="PL">装箱单</button>';$('packing-list-preview').before(tabs);for(const button of tabs.querySelectorAll('button'))button.onclick=async()=>{button.disabled=true;try{const r=await API.request('/shipping/'+id+(button.dataset.documentSheet==='INV'?'/invoice/preview':'/packing-list/preview'));this.drawPreview(r.layout);for(const b of tabs.querySelectorAll('button'))b.className='button '+(b===button?'primary':'secondary');}catch(e){notify(e.message);}finally{button.disabled=false;}};}I18n.apply();};
